```ts
export type ButtonState = 'default' | 'hover' | 'focus-visible' | 'disabled'

export const TOKENS = {
  actionBg: 'var(--color-action-bg)',
  actionFg: 'var(--color-action-fg)',
  actionBgHover: 'var(--color-action-bg-hover)',
  focusRing: 'var(--color-focus-ring)',
  disabledBg: 'var(--color-disabled-bg)',
  disabledFg: 'var(--color-disabled-fg)',
  space1: 'var(--space-1)'
} as const

export function getButtonStyle(state: ButtonState) {
  switch (state) {
    case 'default':
      return { background: TOKENS.actionBg, color: TOKENS.actionFg }
    case 'hover':
      return { background: TOKENS.actionBg, color: TOKENS.actionFg }
    case 'focus-visible':
      return { background: TOKENS.actionBg, color: TOKENS.actionFg, outline: 'none', outlineOffset: TOKENS.space1 }
    case 'disabled':
      return { background: TOKENS.actionBg, color: TOKENS.actionFg, opacity: '0.5', cursor: 'not-allowed' }
  }
}
```

