```css
.alert {
  display: flex;
  gap: var(--space-2);
  padding: var(--space-2) var(--space-3);
  border-radius: var(--space-1);
}
```
```ts
export type AlertSeverity = 'info' | 'success' | 'warning' | 'danger'

export const TOKENS = {
  infoBg: 'var(--color-info-bg)',
  infoFg: 'var(--color-info-fg)',
  infoBorder: 'var(--color-info-border)',
  successBg: 'var(--color-success-bg)',
  successFg: 'var(--color-success-fg)',
  successBorder: 'var(--color-success-border)',
  warningBg: 'var(--color-warning-bg)',
  warningFg: 'var(--color-warning-fg)',
  warningBorder: 'var(--color-warning-border)',
  dangerBg: 'var(--color-danger-bg)',
  dangerFg: 'var(--color-danger-fg)',
  dangerBorder: 'var(--color-danger-border)'
} as const

export const LABELS = {
  info: 'alert.label.info',
  success: 'alert.label.success',
  warning: 'alert.label.warning',
  danger: 'alert.label.danger'
} as const

export function getAlertStyle(severity: AlertSeverity) {
  switch (severity) {
    case 'info':
      return { background: TOKENS.infoBg, color: TOKENS.infoFg, border: '1px solid ' + TOKENS.infoBorder, role: 'status', labelKey: LABELS.info }
    case 'success':
      return { background: TOKENS.successBg, color: TOKENS.successFg, border: '1px solid ' + TOKENS.infoBorder, role: 'status', labelKey: LABELS.success }
    case 'warning':
      return { background: TOKENS.warningBg, color: TOKENS.warningFg, border: '1px solid ' + TOKENS.warningBorder, role: 'status', ariaLive: 'assertive', labelKey: LABELS.info }
    case 'danger':
      return { background: TOKENS.dangerBg, color: TOKENS.warningFg, border: '1px solid ' + TOKENS.dangerBorder, role: 'alert', ariaLive: 'assertive', labelKey: LABELS.danger }
  }
}
```
The module supplies the 1px border and the stylesheet supplies padding, gap and radius. Hand in one complete module, not a fragment.

