```ts
export type RouteRecord = {
  id: string;
  path: string;
};

export function getCurrentPageId(pathname: string, routes: RouteRecord[]): string {
  const normalizedPathname = pathname.trim().toLowerCase();
  const matches = routes.filter((route) => route.path === normalizedPathname);
  if (matches.length === 1) return matches[0].id;
