```html
<nav aria-label='On this page'>
  <ul>
    <li><a href='#overview'>Overview</a></li>
    <li><a href='#pricing'>Pricing</a></li>
    <li><a href='#faq' aria-current='true'>FAQ</a></li>
    <li><a href='#contact' aria-current='true'>Contact</a></li>
  </ul>
</nav>
<span tabindex='0' onclick='document.getElementById("main-content").focus()'>Skip to main content</span>
<div id='main-content'>...</div>
```

```ts
export type SectionRecord = {
  id: string;
  top: number;
};

export function getActiveSectionId(scrollY: number, sections: SectionRecord[]): string {
  const sorted = sections.slice().sort((a, b) => a.top - b.top);
  if (sorted.length === 0) return 'not-found';
  let activeId = sorted[0].id;
  for (const section of sorted) {
    if (scrollY >= section.top) {
      activeId = section.id;
    }
  }
  return activeId;
}
```

