Fictional single-module reducer under review. reduceTableState(state, action) takes the current state and one action and returns a new state. resolveTableState(state) applies sorting, filtering and paging and returns { total, rows }. The types, ROWS and both functions live in this same module, so any patch must keep them in scope and the corrected module you hand over must include them in one block with no imports.

```ts
export type Row = { id: string; name: string; sizeKiB: number; status: 'ready' | 'queued' };
export type SortKey = 'id' | 'sizeKiB';
export type StatusFilter = 'all' | 'ready' | 'queued';
export type TableState = { sortKey: SortKey; sortDir: 'asc' | 'desc'; status: StatusFilter; page: number; pageSize: number };
export type Action =
  | { type: 'setSort'; key: SortKey; dir: 'asc' | 'desc' }
  | { type: 'setStatus'; status: StatusFilter }
  | { type: 'setPage'; page: number };

export const ROWS: Row[] = [
  { id: 'r-204', name: 'Delta bundle', sizeKiB: 60, status: 'ready' },
  { id: 'r-203', name: 'Cobalt bundle', sizeKiB: 140, status: 'ready' },
  { id: 'r-205', name: 'Echo bundle', sizeKiB: 90, status: 'ready' },
  { id: 'r-201', name: 'Atlas bundle', sizeKiB: 140, status: 'ready' },
  { id: 'r-202', name: 'Beacon bundle', sizeKiB: 90, status: 'queued' },
];

export function reduceTableState(state: TableState, action: Action): TableState {
  switch (action.type) {
    case 'setSort':
      return { ...state, sortKey: action.key, sortDir: action.dir };
    case 'setStatus':
      return { ...state, status: action.status };
    case 'setPage':
      return { ...state, page: action.page };
  }
}

export function resolveTableState(state: TableState) {
  const filtered = ROWS.filter((r) => state.status === 'all' || r.status === state.status);
  const sorted = [...filtered].sort((a, b) => {
    const primary = state.sortKey === 'sizeKiB' ? a.sizeKiB - b.sizeKiB : a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
    return state.sortDir === 'asc' ? primary : -primary;
  });
  const start = (state.page - 1) * state.pageSize;
  return { total: sorted.length, rows: sorted.slice(start, start + state.pageSize) };
}
```

Reviewer observations, unchanged and attributed to this faulty module: reduceTableState({ sortKey: 'sizeKiB', sortDir: 'asc', status: 'ready', page: 2, pageSize: 2 }, { type: 'setSort', key: 'sizeKiB', dir: 'asc' }) returns page 2. resolveTableState({ sortKey: 'sizeKiB', sortDir: 'desc', status: 'ready', page: 1, pageSize: 2 }).rows starts with r-203. reduceTableState({ sortKey: 'id', sortDir: 'asc', status: 'all', page: 3, pageSize: 2 }, { type: 'setStatus', status: 'ready' }) returns page 3.

