Corrected module (one self-contained file, no imports):

```ts
export type Row = { id: string; name: string; sizeKiB: number; status: 'ready' | 'queued' };
export type SortKey = 'id' | 'sizeKiB';
export type StatusFilter = 'all' | 'ready' | 'queued';
export type TableState = { sortKey: SortKey; sortDir: 'asc' | 'desc'; status: StatusFilter; page: number; pageSize: number };
export type Action =
  | { type: 'setSort'; key: SortKey; dir: 'asc' | 'desc' }
  | { type: 'setStatus'; status: StatusFilter }
  | { type: 'setPage'; page: number };

export const ROWS: Row[] = [
  { id: 'a-307', name: 'Maple asset', sizeKiB: 45, status: 'ready' },
  { id: 'a-303', name: 'Cedar asset', sizeKiB: 120, status: 'ready' },
  { id: 'a-305', name: 'Birch asset', sizeKiB: 75, status: 'ready' },
  { id: 'a-301', name: 'Aspen asset', sizeKiB: 120, status: 'queued' },
  { id: 'a-306', name: 'Willow asset', sizeKiB: 75, status: 'ready' },
  { id: 'a-302', name: 'Hazel asset', sizeKiB: 30, status: 'queued' },
];

function lastPageOf(total: number, pageSize: number): number {
  return Math.max(1, Math.ceil(total / pageSize));
}

function compareRows(a: Row, b: Row, state: TableState): number {
  const primary = state.sortKey === 'sizeKiB' ? a.sizeKiB - b.sizeKiB : a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
  const directed = state.sortDir === 'asc' ? primary : -primary;
  if (directed !== 0) return directed;
  return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
}

export function reduceTableState(state: TableState, action: Action): TableState {
  switch (action.type) {
    case 'setSort':
      return { ...state, sortKey: action.key, sortDir: action.dir, page: 1 };
    case 'setStatus': {
      const total = ROWS.filter((r) => action.status === 'all' || r.status === action.status).length;
      return { ...state, status: action.status, page: Math.min(state.page, lastPageOf(total, state.pageSize)) };
    }
    case 'setPage':
      return { ...state, page: action.page };
  }
}

export function resolveTableState(state: TableState) {
  const filtered = ROWS.filter((r) => state.status === 'all' || r.status === state.status);
  const sorted = [...filtered].sort((a, b) => compareRows(a, b, state));
  const total = sorted.length;
  const page = Math.min(state.page, lastPageOf(total, state.pageSize));
  const start = (page - 1) * state.pageSize;
  return { total, rows: sorted.slice(start, start + state.pageSize) };
}
```

Handover to Wing Lau. Defect 1: compareRows applied sortDir to the whole comparison, so equal sortKey values fell back to CSV order. Cedar asset a-303 sits before Aspen asset a-301 in the CSV, both at sizeKiB 120, so sizeKiB desc returned a-303 first instead of a-301. Fix: apply sortDir only to the primary comparison, then tie-break by id ascending unconditionally. Defect 2: setStatus never clamped the page. Filtering the six rows to 'ready' leaves four rows, so with pageSize 2 lastPage is 2 and the stored page 3 must return 2. Fix: compute lastPage from the filtered count and return Math.min(page, lastPage). Defect 3: resolveTableState sliced from the raw page, so page 4 returned rows [] while total was 6. Fix: clamp the effective page before slicing, giving rows a-306 and a-307. Tests to run: the three observations above, a setSort case expecting page 1, and an immutability check on ROWS and the input state. Limitations: read-only review, nothing executed, and sort stability plus Math.ceil are assumed.

