```ts
export type MerchantUpdateRequest = {
  requestId: string
  merchantId: string
  sku: string
  priceCents: number
  currency: string
  note?: string
}

export type TransactionResult =
  | { status: 'accepted'; eventId: string; merchantId: string; sku: string; priceCents: number; currency: string }
  | { status: 'validation_failed'; errorCode: string; message: string }
  | { status: 'duplicate'; originalEventId: string }

export type AuditEvent = {
  eventId: string
  merchantId: string
  sku: string
  priceCents: number
  currency: string
  note?: string
}

export function buildAuditEvent(
  request: MerchantUpdateRequest,
  result: TransactionResult
): AuditEvent[] {
  const events: AuditEvent[] = []
  if (result.status !== 'accepted') {
    events.push({
      eventId: 'error',
      merchantId: request.merchantId,
      sku: request.sku,
      priceCents: request.priceCents,
      currency: request.currency,
      note: request.note,
    })
  } else {
    events.push({
      eventId: result.eventId,
      merchantId: request.merchantId,
      sku: request.sku,
      priceCents: request.priceCents,
      currency: request.currency,
      note: request.note,
    })
  }
  return events
}
```
Contract: The builder receives a merchant update request and a transaction result. It must return exactly one AuditEvent for an accepted result, using eventId, merchantId, sku, priceCents, currency from the result and note from the request. For validation_failed or duplicate, it must return null. The shown code violates this contract.

