Defective builder and explicit contract. The snippet below is fictional code for this simulation.

```ts
export type PriceUpdateRequest = {
  requestId: string
  merchantId: string
  sku: string
  requestedPriceCents: number
  currency: string
  note?: string
}

export type UpdateResult =
  | { status: 'updated'; eventId: string; merchantId: string; sku: string; oldPriceCents: number; newPriceCents: number; currency: string }
  | { status: 'unchanged'; merchantId: string; sku: string; priceCents: number; currency: string }
  | { status: 'validation_failed'; errorCode: string }

export type AuditEvent = {
  eventId: string
  merchantId: string
  sku: string
  oldPriceCents: number
  newPriceCents: number
  currency: string
  note?: string
}

export function buildAuditEvent(
  request: PriceUpdateRequest,
  result: UpdateResult
): AuditEvent[] {
  const events: AuditEvent[] = []
  if (result.status !== 'validation_failed') {
    events.push({
      eventId: 'pending',
      merchantId: request.merchantId,
      sku: request.sku,
      oldPriceCents: request.requestedPriceCents,
      newPriceCents: request.requestedPriceCents,
      currency: request.currency,
      note: request.note,
    })
  }
  if (result.status === 'updated') {
    events.push({
      eventId: result.eventId,
      merchantId: result.merchantId,
      sku: result.sku,
      oldPriceCents: result.oldPriceCents,
      newPriceCents: result.newPriceCents,
      currency: result.currency,
      note: request.note,
    })
  }
  return events
}
```

Contract. buildAuditEvent is pure and takes a PriceUpdateRequest and a caller supplied UpdateResult. It must return exactly one AuditEvent when the result status is 'updated', and null for 'unchanged' and 'validation_failed'. The fields eventId, merchantId, sku, oldPriceCents, newPriceCents and currency come from the transaction result. The optional note comes from the request. The snippet above violates this contract.

