```ts
// src/cache/selectCacheEntry.ts
export type CacheRecord = {
  id: string
  tenantId: string
  path: string
  storedAt: string
  expiresAt: string
  version: number
}

export type CacheSelection = {
  hit: boolean
  recordId: string | null
}

export function selectCacheEntry(
  now: string,
  tenantId: string,
  path: string,
  records: CacheRecord[]
): CacheSelection {
  let best: CacheRecord | null = null
  for (const record of records) {
    if (record.path !== path) continue
    if (record.expiresAt < now) continue
    if (best === null || record.storedAt > best.storedAt) {
      best = record
    }
  }
  return { hit: best !== null, recordId: best === null ? null : best.id }
}
```

