Fictional SHOPLINE simulation code supplied for reading only, no execution. mapQuery already follows search-contract. handleResponse currently has exactly one defect for empty results. Reading the exact program: mapQuery trims q, defaults page to 1 when page is not greater than 0, clamps pageSize between 1 and 50, and falls back to relevance for any other sort value. handleResponse reads res.items[0].id before checking total.

```ts
export type SortKey = 'relevance' | 'price_asc' | 'price_desc'

export type SearchRequest = {
  q?: string
  page: number
  pageSize: number
  sort: SortKey
}

export type SearchResponse = {
  total: number
  page: number
  pageSize: number
  items: { id: string; title: string; priceHkd: number }[]
}

export function mapQuery(raw: { q: string; page: number; pageSize: number; sort: string }): SearchRequest {
  const trimmed = raw.q.trim()
  const page = raw.page > 0 ? raw.page : 1
  const pageSize = Math.min(Math.max(raw.pageSize, 1), 50)
  const sort: SortKey =
    raw.sort === 'price_asc' || raw.sort === 'price_desc' ? raw.sort : 'relevance'
  return trimmed === ''
    ? { page, pageSize, sort }
    : { q: trimmed, page, pageSize, sort }
}

export type ViewState =
  | { kind: 'idle' }
  | { kind: 'results'; firstId: string; count: number }
  | { kind: 'empty' }

export function handleResponse(res: SearchResponse): ViewState {
  return { kind: 'results', firstId: res.items[0].id, count: res.total }
}
```

