Fictional SHOPLINE simulation code supplied for reading only, no execution. mapQuery conforms to search-contract, including the limit rule that sends any out-of-range value to 15. handleResponse has one reported defect: it reads res.items[0].id without first checking whether the page is empty, so a valid empty page does not return { kind: 'empty' }. Everything else in the program, including the availabilityApplied calculation, matches the contract and must be preserved.

```ts
export type SortKey = 'relevance' | 'price_asc' | 'price_desc'
export type Availability = 'in_stock' | 'preorder' | 'any'

export type SearchRequest = {
  term?: string
  cursor?: string
  limit: number
  availability: Availability
  sort: SortKey
}

export type SearchResponse = {
  items: { id: string; title: string; priceHkd: number }[]
  nextCursor: string | null
  unavailableFilters: string[]
}

export type ViewState =
  | { kind: 'idle' }
  | {
      kind: 'results'
      firstId: string
      count: number
      nextCursor: string | null
      availabilityApplied: boolean
    }
  | { kind: 'empty' }

export function mapQuery(raw: {
  term: string
  cursor: string
  limit: number
  availability: string
  sort: string
}): SearchRequest {
  const term = raw.term.trim()
  const cursor = raw.cursor.trim()
  const limit =
    raw.limit >= 1 && raw.limit <= 40 ? raw.limit : 15
  const availability: Availability =
    raw.availability === 'in_stock' || raw.availability === 'preorder'
      ? raw.availability
      : 'any'
  const sort: SortKey =
    raw.sort === 'price_asc' || raw.sort === 'price_desc'
      ? raw.sort
      : 'relevance'
  const base = { limit, availability, sort }
  const withCursor = cursor === '' ? base : { ...base, cursor }
  return term === '' ? withCursor : { term, ...withCursor }
}

export function handleResponse(res: SearchResponse): ViewState {
  return {
    kind: 'results',
    firstId: res.items[0].id,
    count: res.items.length,
    nextCursor: res.nextCursor,
    availabilityApplied: !res.unavailableFilters.includes('availability'),
  }
}
```

