Fictional Oursky learning simulation. The module below is the complete current dependency adapter, supplied for reading only. Supplied CI observation: toDisplayLabel('  Lab-Rack  ') throws TypeError: normalizeTag(...).toUpperCase is not a function, because normalizeTag returns a tagged object and the adapter still treats it as a string. The CSV lists raw input only, with no expected labels. Machine identifiers, code and case values stay byte-identical in both locales.

```ts
export type NormalizedTag =
  | { kind: 'ok'; value: string }
  | { kind: 'empty' }
  | { kind: 'invalid'; code: 'too_long' | 'bad_char' };

export function normalizeTag(raw: string): NormalizedTag {
  const normalized = raw.trim().toLowerCase();
  if (normalized.length === 0) return { kind: 'empty' };
  if (normalized.length > 12) return { kind: 'invalid', code: 'too_long' };
  if (!/^[a-z0-9-]+$/.test(normalized)) return { kind: 'invalid', code: 'bad_char' };
  return { kind: 'ok', value: normalized };
}

export function toDisplayLabel(raw: string): string {
  return normalizeTag(raw).toUpperCase();
}
```

