Fictional handover. Defect: toDisplayLabel calls toUpperCase on the tagged object returned by normalizeTag, so the supplied check throws TypeError: normalizeTag(...).toUpperCase is not a function. Fix: branch on result.kind and keep normalizeTag unchanged.

```ts
export type NormalizedTag =
  | { kind: 'ok'; value: string }
  | { kind: 'empty' }
  | { kind: 'invalid'; code: 'too_long' | 'bad_char' };

export function normalizeTag(raw: string): NormalizedTag {
  const normalized = raw.trim().toLowerCase();
  if (normalized.length === 0) return { kind: 'empty' };
  if (normalized.length > 12) return { kind: 'invalid', code: 'too_long' };
  if (!/^[a-z0-9-]+$/.test(normalized)) return { kind: 'invalid', code: 'bad_char' };
  return { kind: 'ok', value: normalized };
}

export function toDisplayLabel(raw: string): string {
  const result = normalizeTag(raw);
  if (result.kind === 'ok') return result.value.toUpperCase();
  if (result.kind === 'empty') return 'UNTAGGED';
  return result.code === 'too_long' ? 'INVALID_TOO_LONG' : 'INVALID_BAD_CHAR';
}
```

Evidence: tag-01 gives LAB-RACK, tag-02 UNTAGGED, tag-03 INVALID_BAD_CHAR because of its underscore, tag-04 INVALID_TOO_LONG at 13 normalized characters, tag-05 EDGE-01 with 7 characters, tag-06 INVALID_BAD_CHAR because the interior space survives trim, tag-07 INVALID_TOO_LONG because 14 normalized characters hit the length rule before the character rule. Boundary: abcdefghijkl at 12 characters is ok while abcdefghijklm at 13 is too_long. Verification: assert these exact strings for all seven case ids plus both boundary inputs, and assert every branch returns a string. Limitation: paper review only, with no execution and no production validation.

