Fictional Oursky learning simulation. The single fenced block below is the complete current module, supplied for reading only. It contains the exported type, the slot table, readSlot and the adapter, so it is self-contained and importable as shown. Supplied continuous integration observation: formatSlotLabel('  hk-cw-01  ') throws TypeError: readSlot(...).toFixed is not a function, because readSlot returns a tagged object and the adapter still treats it as a number. The CSV lists raw input only, with no expected labels. Machine identifiers, code and case values stay byte-identical in both locales.

```ts
export type SlotReading =
  | { kind: 'ok'; celsius: number }
  | { kind: 'empty' }
  | { kind: 'error'; code: 'unknown_slot' | 'out_of_range' };

const SLOTS: Record<string, number | null> = {
  'HK-CW-01': 4.2,
  'HK-CW-02': null,
  'HK-KT-07': -5.0,
  'HK-KT-08': 8.0,
  'HK-ST-03': 9.4,
  'HK-ST-04': -6.1,
};

export function readSlot(slotKey: string): SlotReading {
  const normalized = slotKey.trim().toUpperCase();
  if (!(normalized in SLOTS)) return { kind: 'error', code: 'unknown_slot' };
  const value = SLOTS[normalized];
  if (value === null) return { kind: 'empty' };
  if (value < -5.0 || value > 8.0) return { kind: 'error', code: 'out_of_range' };
  return { kind: 'ok', celsius: value };
}

export function formatSlotLabel(slotKey: string): string {
  return readSlot(slotKey).toFixed(1) + ' C';
}
```

