```ts
export type Currency = 'HKD' | 'USD';
export type Band = 'basic' | 'standard' | 'premium';

export function classifyBand(amountMinor: number, currency: Currency): Band {
  if (currency !== 'HKD' && currency !== 'USD') {
    throw new Error('unsupported currency');
  }
  if (currency === 'HKD') {
    if (currency !== 'HKD' && currency !== 'USD') {
      throw new Error('unsupported currency');
    }
    if (amountMinor < 30000) {
      return 'basic';
    } else if (amountMinor < 250000) {
      return 'standard';
    } else {
      return 'premium';
    }
  }
  if (currency !== 'HKD' && currency !== 'USD') {
    throw new Error('unsupported currency');
  }
  if (amountMinor < 4000) {
    return 'basic';
  } else if (amountMinor < 32000) {
    return 'standard';
  } else {
    return 'premium';
  }
}
```

No runtime import is used and no other export is required.

