    return 'basic';
  } else if (amountMinor < 32000) {
    return 'standard';
  } else {
    return 'premium';
  }
}
```

此模組不使用執行期匯入，亦不需要其他匯出。

exemplar.en:
Decision. Replace both parallel currency cascades and the three repeated guards with one explicit runtime guard plus one shared comparison cascade driven by per-currency threshold lookups. Evidence from starter-module: the guard 'currency !== HKD && currency !== USD' appears three times, and the same two-step cascade is written once for HKD and once for USD. The policy also requires the guard to test the currency string itself, so detecting invalid currencies only by an undefined lookup is not acceptable since 'toString' is not undefined.

```ts
export type Currency = 'HKD' | 'USD';
export type Band = 'basic' | 'standard' | 'premium';

const STANDARD_MINOR: Record<Currency, number> = { HKD: 30000, USD: 4000 };
const PREMIUM_MINOR: Record<Currency, number> = { HKD: 250000, USD: 32000 };

export function classifyBand(amountMinor: number, currency: Currency): Band {
  if (currency !== 'HKD' && currency !== 'USD') {
    throw new Error('unsupported currency');
  }
  if (amountMinor < STANDARD_MINOR[currency]) {
    return 'basic';
  }
  if (amountMinor < PREMIUM_MINOR[currency]) {
    return 'standard';
  }
  return 'premium';
}
```

Band results from policy-bands against trace-table: pb-01 basic, pb-02 basic, pb-03 standard, pb-04 standard, pb-05 premium, pb-06 basic, pb-07 standard, pb-08 standard, so four rows return 'standard'. classifyBand(32000,'USD') returns 'premium' because 32000 is not below the USD premium threshold. Proposed tests: eight boundary cases plus 'JPY' and 'toString', ten in total. Limitations: no code was executed here, and the trace table alone does not cover every boundary value.

