body.en:
Fictional module. The verdicts are already correct. The defect is the duplicated cascade, not wrong behaviour. Contract: input is a raw string, output is one of 'empty', 'unsupported-extension', 'name-too-long' or 'accepted'. No runtime import is used and no other export is required.

```ts
export type Verdict = 'empty' | 'unsupported-extension' | 'name-too-long' | 'accepted';

const MAX_BASE_LENGTH = 40;

export function checkFilename(raw: string): Verdict {
  const normalised = raw.trim().toLowerCase();
  if (normalised.length === 0) {
    return 'empty';
  }
  const dot = normalised.lastIndexOf('.');
  if (dot < 1) {
    return 'unsupported-extension';
  }
  const ext = normalised.slice(dot + 1);
  if (ext !== 'png' && ext !== 'jpg' && ext !== 'webp') {
    return 'unsupported-extension';
  }
  const base = normalised.slice(0, dot);
  if (base.length > MAX_BASE_LENGTH) {
    return 'name-too-long';
  }
  const again = raw.trim().toLowerCase();
  if (again.length === 0) {
    return 'empty';
  }
  const againDot = again.lastIndexOf('.');
  if (againDot < 1) {
    return 'unsupported-extension';
  }
  const againExt = again.slice(againDot + 1);
  if (againExt !== 'png' && againExt !== 'jpg' && againExt !== 'webp') {
    return 'unsupported-extension';
  }
  const againBase = again.slice(0, againDot);
  if (againBase.length > MAX_BASE_LENGTH) {
    return 'name-too-long';
  }
  return 'accepted';
}
```

body.zh:
